import csv
import io
import re
from typing import List, Tuple


EXPECTED_WIDTH = 14


def _read_records(raw_csv: str) -> List[List[str]]:
    try:
        return [
            row
            for row in csv.reader(
                io.StringIO(raw_csv, newline=""),
                delimiter=",",
                quotechar='"',
                doublequote=True,
                strict=False,
            )
        ]
    except csv.Error:
        records = []
        for line in raw_csv.splitlines():
            try:
                records.extend(
                    csv.reader(
                        [line],
                        delimiter=",",
                        quotechar='"',
                        doublequote=True,
                        strict=False,
                    )
                )
            except csv.Error:
                records.append([line])
        return records


def _header_score(row: List[str]) -> int:
    nonempty = [value.strip().lstrip("\ufeff") for value in row if value.strip()]
    if not nonempty:
        return 0
    identifiers = sum(
        1 for value in nonempty if re.fullmatch(r"[A-Za-z][A-Za-z0-9_]*", value)
    )
    if len(row) == EXPECTED_WIDTH and identifiers >= 6:
        return identifiers
    return 0


def _fit_width(row: List[str], width: int) -> List[str]:
    if len(row) > width:
        row = row[: width - 1] + [",".join(row[width - 1 :])]
    elif len(row) < width:
        row = row + [""] * (width - len(row))
    return row


def parse_csv(raw_csv: str):
    records = _read_records(raw_csv)
    nonblank = [
        (index, row)
        for index, row in enumerate(records)
        if row and any(value.strip() for value in row)
    ]

    if not nonblank:
        return {
            "columns": [f"column_{index + 1}" for index in range(EXPECTED_WIDTH)],
            "rows": [],
        }

    header_index = None
    best_score = 0
    for index, row in nonblank:
        score = _header_score(row)
        if score > best_score:
            header_index = index
            best_score = score

    if header_index is None:
        header_index, header = nonblank[0]
    else:
        header = records[header_index]

    header = [value.lstrip("\ufeff") if i == 0 else value for i, value in enumerate(header)]
    header = _fit_width(header, EXPECTED_WIDTH)
    for index, value in enumerate(header):
        if not value:
            header[index] = f"column_{index + 1}"

    rows = []
    for index, row in nonblank:
        if index <= header_index:
            continue
        rows.append(_fit_width(list(row), len(header)))

    return {"columns": header, "rows": rows}
